require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$severity=$_GET['severity']??'';$params=[];$filter='';if(in_array($severity,['info','warning','high'],true)){$filter=' WHERE se.severity=?';$params[]=$severity;}$q=db()->prepare("SELECT se.*,u.email user_email FROM security_events se LEFT JOIN users u ON u.id=se.user_id $filter ORDER BY se.created_at DESC LIMIT 500");$q->execute($params);$rows=$q->fetchAll();$pageTitle='Security Monitoring';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>Security events</h1><p class="page-note">Review authentication failures, lockouts, role denials, MFA failures and protected-data access denials.</p></div><a class="btn btn-outline" href="<?=e(url('admin/export.php?type=security'))?>">Export CSV</a></div><?=admin_nav()?><div class="toolbar"><form method="get"><select name="severity"><option value="">All severities</option><option value="info" <?=$severity==='info'?'selected':''?>>Info</option><option value="warning" <?=$severity==='warning'?'selected':''?>>Warning</option><option value="high" <?=$severity==='high'?'selected':''?>>High</option></select><button class="btn btn-sm">Filter</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Severity</th><th>Event</th><th>User / Attempt</th><th>IP</th><th>Description</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No security events.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><span class="badge <?=$r['severity']==='high'?'red':($r['severity']==='warning'?'amber':'gray')?>"><?=e($r['severity'])?></span></td><td><?=e($r['event_type'])?></td><td><?=e($r['user_email']??$r['email_attempt']??'—')?></td><td><?=e($r['ip_address']??'—')?></td><td><?=e($r['description'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
